   103	// with no other characters anywhere. Consequences, all measured:
   104	//   accept: "16" "  16  " "\t42\n" "+16" "-5" "1_6" "016" "１２" "٣"
   105	//   reject: "" "-" "0x10" "0b101" "1e5" "1.5" "abc" "1_" "_1" "1__2" "4 2" "- 5"
   106	export const UNDERSCORE = 0x5f;
   107	export const PLUS_SIGN = 0x2b;
   108	export const MINUS_SIGN = 0x2d;
