   110	/**
   111	 * Python's int(text) for base 10.
   112	 * @param {string} text
   113	 * @returns {{ok: true, value: bigint} | {ok: false}}
   114	 */
   115	export function pyIntFromString(text) {
   116	  const cps = Array.from(text, (ch) => ch.codePointAt(0));
   117	
   118	  let start = 0;
   119	  let end = cps.length;
   120	  while (start < end && isPyWhitespace(cps[start])) start += 1;
   121	  while (end > start && isPyWhitespace(cps[end - 1])) end -= 1;
   122	
   123	  let i = start;
   124	  let negative = false;
   125	  if (i < end && (cps[i] === PLUS_SIGN || cps[i] === MINUS_SIGN)) {
   126	    negative = cps[i] === MINUS_SIGN;
   127	    i += 1;
   128	  }
   129	
   130	  // At least one digit is required immediately after the optional sign: this is
   131	  // what rejects "", "-", "_1" and "- 5".
   132	  let value = 0n;
   133	  let digitCount = 0;
   134	  let previousWasUnderscore = false;
   135	
   136	  while (i < end) {
   137	    const cp = cps[i];
   138	    if (cp === UNDERSCORE) {
   139	      // An underscore is legal only strictly between two digits.
   140	      if (digitCount === 0 || previousWasUnderscore) return { ok: false };
   141	      previousWasUnderscore = true;
   142	      i += 1;
   143	      continue;
   144	    }
   145	    const digit = unicodeDigitValue(cp);
   146	    if (digit < 0) return { ok: false };
   147	    value = value * 10n + BigInt(digit);
   148	    digitCount += 1;
   149	    previousWasUnderscore = false;
   150	    i += 1;
   151	  }
   152	
   153	  if (digitCount === 0) return { ok: false }; // no digits at all
   154	  if (previousWasUnderscore) return { ok: false }; // trailing "_"
   155	
   156	  return { ok: true, value: negative ? -value : value };
   157	}
