   196	  const quote = chooseQuote(chars.includes("'"), chars.includes('"'));
   197	
   198	  let body = '';
   199	  for (const ch of chars) {
   200	    if (ch === quote) {
   201	      body += '\\' + quote;
   202	    } else if (STR_SHORT_ESCAPES.has(ch)) {
